fn main() {
 let duration: f32 = 1e-20; let rate: f32 = 2e20;
 let action = (duration * rate).round().max(1.0) as u64;
 let phase = 1.0f32 / action as f32;
 let profile: [f32; 5] = [0.0,0.1,0.3,0.6,1.0];
 let segment = ((phase * 4.0).floor() as usize).min(3);
 let u = phase * 4.0 - segment as f32;
 let secants: [f32;4] = std::array::from_fn(|i| (profile[i+1]-profile[i])*4.0);
 let mut tangents = [0.0f32;5];
 for i in 1..4 { let before=secants[i-1]; let after=secants[i]; if before>0.0 && after>0.0 { tangents[i]=2.0*before*after/(before+after); } }
 let (p0,p1,m0,m1)=(profile[segment],profile[segment+1],tangents[segment]*0.25,tangents[segment+1]*0.25);
 let u2=u*u; let derivative=(6.0*u2-6.0*u)*p0+(3.0*u2-4.0*u+1.0)*m0+(-6.0*u2+6.0*u)*p1+(3.0*u2-2.0*u)*m1;
 let second=(12.0*u-6.0)*p0+(6.0*u-4.0)*m0+(-12.0*u+6.0)*p1+(6.0*u-2.0)*m1;
 let speed=derivative*4.0/duration; let acceleration=second*16.0/(duration*duration);
 println!("duration={duration:e} rate={rate:e} reciprocal={:e} samples={action} phase={phase} speed={speed:e} speed_finite={} acceleration={acceleration} acceleration_finite={}",rate.recip(),speed.is_finite(),acceleration.is_finite());
}
